// Observations and ambitions are separate: fit history first, then a dated target scenario.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const newMetrics=()=>({customers:50000,billers:'',changedOn:'2026-04-01',targetOn:'2026-10-01',budget:12,timelyDays:5,rows:[{id:'invoice_timeliness',before:'99',after:'94',target:'99'}]});
export function metricsMarkup(draft,dictionary){const m=draft.metricDraft||newMetrics(),kpis=dictionary?.kpis||[];
 return `<div class="metrics-intro"><span class="path-label">MATCH EXISTING METRICS</span><p>Tell us what changed and what you want to achieve. The local engine will find settings that approximate your observations and build a dated recovery scenario.</p></div><div class="metric-known"><label>Customer accounts<input type="number" data-metric="customers" min="20" max="600000" value="${esc(m.customers)}" required></label><label>Billing analysts <span>if known</span><input type="number" data-metric="billers" min="0" max="5000" value="${esc(m.billers)}"></label><label>When did things change?<input type="date" data-metric="changedOn" min="2026-01-01" max="2026-12-31" value="${esc(m.changedOn)}" required></label><label>When should the improvement start?<input type="date" data-metric="targetOn" min="2026-01-01" max="2026-12-31" value="${esc(m.targetOn)}" required></label></div><div class="metric-rows">${m.rows.map((r,i)=>{const k=kpis.find(k=>k.id===r.id);return `<fieldset class="metric-row" data-metric-row="${i}"><legend>Metric ${i+1}</legend><label class="metric-choice">KPI<select data-row-field="id" ${kpis.length?'':'disabled'}>${kpis.map(k=>`<option value="${esc(k.id)}" ${k.id===r.id?'selected':''}>${esc(k.label)}</option>`).join('')}</select></label>${['before','after','target'].map((f,n)=>`<label>${['Where it was','Where it went','Where it needs to be'][n]}<span>${k?.unit==='share'?'Percent':k?.unit==='days'?'Days':'Per 1,000 accounts / year'}</span><input type="number" data-row-field="${f}" step="any" min="0" ${k?.unit==='share'?'max="100"':''} value="${esc(r[f])}" ${f==='after'?'required':''}></label>`).join('')}<button type="button" class="text-button metric-remove" data-remove-metric="${i}" ${m.rows.length===1?'disabled':''}>Remove</button><p>${esc(k?.description||'Loading the engine’s KPI definitions…')}</p></fieldset>`;}).join('')}</div><button type="button" class="secondary" id="add-metric" ${m.rows.length>=12?'disabled':''}>＋ Add a KPI</button><details class="metric-fit-options"><summary>Fitting options</summary><div class="metric-known"><label>Replay budget per fit<input type="number" data-metric="budget" min="2" max="40" value="${esc(m.budget)}"></label><label>Invoice timeliness window (days)<input type="number" data-metric="timelyDays" min="1" max="60" value="${esc(m.timelyDays)}"></label></div><p>Fitting uses a calibration town. A target may be outside the engine’s range; the review shows what it could reproduce. All calculations run locally.</p></details>`;
}
export function bindMetrics(root,draft,{save,render}){draft.metricDraft||=newMetrics();const m=draft.metricDraft;
 for(const el of root.querySelectorAll('[data-metric]'))el.oninput=()=>{m[el.dataset.metric]=el.value;draft.metricReport=null;save();};
 for(const el of root.querySelectorAll('[data-row-field]'))el.onchange=()=>{const r=m.rows[Number(el.closest('[data-metric-row]').dataset.metricRow)];r[el.dataset.rowField]=el.value;draft.metricReport=null;save();if(el.dataset.rowField==='id')render();};
 root.querySelector('#add-metric')?.addEventListener('click',()=>{m.rows.push({id:'missed_read_share',before:'',after:'',target:''});save();render();});
 for(const b of root.querySelectorAll('[data-remove-metric]'))b.onclick=()=>{m.rows.splice(Number(b.dataset.removeMetric),1);save();render();};
}
export function metricSpecs(draft,dictionary){const m=draft.metricDraft||newMetrics(),seen=new Set();
 const number=(v,label)=>{if(String(v??'').trim()===''||!Number.isFinite(Number(v))||Number(v)<0)throw Error(label+' needs a non-negative number.');return Number(v);};
 const rows=m.rows.map(r=>{const k=dictionary?.kpis?.find(k=>k.id===r.id);if(!k)throw Error('Choose a KPI from the engine’s dictionary.');if(seen.has(r.id))throw Error('Choose each KPI once.');seen.add(r.id);const n=v=>{const value=number(v,k.label);if(k.unit==='share'&&value>100)throw Error(k.label+' must be between 0 and 100%.');return k.unit==='share'?value/100:value;};return {id:r.id,before:String(r.before??'').trim()?n(r.before):undefined,after:n(r.after),target:String(r.target??'').trim()?n(r.target):undefined};});
 if(rows.some(r=>r.target!==undefined)&&m.targetOn<=m.changedOn)throw Error('The improvement must start after the observed change.');
 const base={name:draft.name,customers:number(m.customers,'Customer accounts'),...(String(m.billers).trim()?{billers:number(m.billers,'Billing analysts')}:{}),calibration:'village',budget:number(m.budget,'Replay budget'),timelyDays:number(m.timelyDays,'Timeliness window'),asOf:'2026-12-31',seed:draft.seed||''};
 return {history:{...base,changedOn:m.changedOn,kpis:rows.map(({target,...r})=>r)},target:rows.some(r=>r.target!==undefined)?{...base,kpis:rows.filter(r=>r.target!==undefined).map(r=>({id:r.id,value:r.target}))}:null};
}
export async function fitMetrics(draft,dictionary,{api='/api',fetchImpl=globalThis.fetch,onProgress=()=>{}}={}){const specs=metricSpecs(draft,dictionary);
 const fit=async(spec,label)=>{onProgress(label);const r=await fetchImpl(api+'/twin/fit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(spec)});const out=await r.json();if(!r.ok)throw Error(typeof out.detail==='string'?out.detail:JSON.stringify(out.detail));return out;};
 const history=await fit(specs.history,'Replaying your observed KPIs on this computer…');let target=null;const proposal=structuredClone(history.proposal);
 if(specs.target){target=await fit(specs.target,'Finding settings for your improvement target…');proposal.episodes.push({title:'Towards your KPI targets',from:draft.metricDraft.targetOn,to:null,ramp:0,settings:target.proposal.settings});}
 const report={history:history.kpis,target:target?.kpis||[],notes:[...history.notes,...(target?.notes||[])],observations:structuredClone(draft.metricDraft)};
 proposal.kpis=[...new Set(draft.metricDraft.rows.map(r=>r.id))];proposal.goals=['everything'];proposal.metricHistory=report;
 return {proposal,report};
}
const metricValue=(v,unit)=>v==null?'Unavailable':unit==='share'?(Number(v)*100).toFixed(2)+'%':Number(v).toLocaleString(undefined,{maximumFractionDigits:2});
export function metricReportMarkup(report){if(!report)return '';return `<section class="metric-report"><h2>How closely the engine matched</h2><p>These are achieved calibration values, not a guarantee for the full utility. The target fit proposes a future scenario; replay the year to see its outcome alongside your history.</p><div class="metric-report-table"><table><thead><tr><th>KPI</th><th>Period</th><th>Requested</th><th>Achieved</th><th>Fit</th></tr></thead><tbody>${[...(report.history||[]).map(r=>({...r,stage:r.period})),...(report.target||[]).map(r=>({...r,stage:'Target scenario'}))].map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.stage)}</td><td>${esc(metricValue(r.target,r.unit))}</td><td>${esc(metricValue(r.achieved,r.unit))}</td><td><span class="fit-status ${r.status==='fitted'?'fitted':''}">${esc(r.status)}</span></td></tr>`).join('')}</tbody></table></div>${(report.notes||[]).map(n=>`<p class="field-note">${esc(n)}</p>`).join('')}</section>`;}
